const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2,7);
const defaultTrip = () => ({id:uid(),name:"",destination:"",startDate:"",endDate:"",coverEmoji:"✈️",places:[],itinerary:[],expenses:[],notes:[],packing:[],currency:"PLN",destLat:null,destLng:null});
function saveTrips(t){try{localStorage.setItem("voyager-data",JSON.stringify(t))}catch(e){}}
function loadTrips(){try{const d=localStorage.getItem("voyager-data");return d?JSON.parse(d):[]}catch(e){return[]}}
function saveApiKey(k){try{localStorage.setItem("voyager-apikey",k)}catch(e){}}
function loadApiKey(){try{return localStorage.getItem("voyager-apikey")||""}catch(e){return""}}
function saveDark(v){try{localStorage.setItem("voyager-dark",v?"1":"0")}catch(e){}}
function loadDark(){try{return localStorage.getItem("voyager-dark")==="1"}catch(e){return false}}

const DarkCtx=createContext(false);

const compressImage=(file,maxDim=800,quality=0.6)=>new Promise((resolve)=>{const reader=new FileReader();reader.onload=(e)=>{const img=new Image();img.onload=()=>{const canvas=document.createElement("canvas");let w=img.width,h=img.height;if(w>maxDim||h>maxDim){if(w>h){h=(h/w)*maxDim;w=maxDim}else{w=(w/h)*maxDim;h=maxDim}}canvas.width=w;canvas.height=h;canvas.getContext("2d").drawImage(img,0,0,w,h);resolve(canvas.toDataURL("image/jpeg",quality))};img.src=e.target.result};reader.readAsDataURL(file)});

/* ═══ COUNTDOWN ═══ */
function Countdown({startDate,endDate}){const[now,setNow]=useState(new Date());useEffect(()=>{const t=setInterval(()=>setNow(new Date()),60000);return()=>clearInterval(t)},[]);if(!startDate)return null;const start=new Date(startDate+"T00:00:00");const end=endDate?new Date(endDate+"T23:59:59"):null;const diff=start-now;if(diff<=0&&end&&now<=end)return<div style={cdS.box}><div style={cdS.live}>🎉 Podróż w toku!</div></div>;if(diff<=0)return null;const days=Math.floor(diff/864e5);const hours=Math.floor((diff%864e5)/36e5);return(<div style={cdS.box}><div style={{fontSize:13,color:"rgba(255,255,255,.7)",marginBottom:8,fontWeight:600}}>⏳ Do wyjazdu pozostało</div><div style={cdS.nums}><div style={cdS.unit}><div style={cdS.val}>{days}</div><div style={cdS.lbl}>dni</div></div><div style={{fontSize:24,color:"rgba(255,255,255,.3)"}}>:</div><div style={cdS.unit}><div style={cdS.val}>{hours}</div><div style={cdS.lbl}>godz.</div></div></div></div>)}
const cdS={box:{background:"linear-gradient(135deg,#9a3412,#c2410c)",borderRadius:14,padding:20,marginBottom:12,textAlign:"center"},nums:{display:"flex",justifyContent:"center",alignItems:"center",gap:12},unit:{display:"flex",flexDirection:"column",alignItems:"center"},val:{fontSize:36,fontWeight:700,color:"#fff",fontFamily:"'DM Mono',monospace",lineHeight:1},lbl:{fontSize:11,color:"rgba(255,255,255,.6)",marginTop:4},live:{fontSize:18,fontWeight:700,color:"#fff",padding:"8px 0"}};

/* ═══ WEATHER ═══ */
function WeatherWidget({lat,lng,destination,onGeocode}){const dark=useContext(DarkCtx);const wS=dark?wSD:wSL;const[weather,setWeather]=useState(null);const[loading,setLoading]=useState(false);const[error,setError]=useState(null);const[geoLoading,setGeoLoading]=useState(false);const mounted=useRef(true);
const doGeocode=async()=>{if(!destination)return;setGeoLoading(true);try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(destination)}&limit=1`);const d=await r.json();if(d[0]&&onGeocode)onGeocode(+d[0].lat,+d[0].lon)}catch{}setGeoLoading(false)};
useEffect(()=>{mounted.current=true;if(!lat||!lng)return;setLoading(true);setError(null);fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lng}&daily=temperature_2m_max,temperature_2m_min,precipitation_sum,weathercode&current=temperature_2m,weathercode,relative_humidity_2m,wind_speed_10m&timezone=auto&forecast_days=7`).then(r=>r.json()).then(data=>{if(mounted.current){if(data.daily)setWeather(data);else setError("Brak danych")}}).catch(()=>{if(mounted.current)setError("Brak połączenia")}).finally(()=>{if(mounted.current)setLoading(false)});return()=>{mounted.current=false}},[lat,lng]);
if(!lat||!lng)return<div style={wS.box}><div style={wS.hdr}><span style={{fontSize:20}}>🌤️</span><span style={{fontWeight:700}}>Pogoda</span></div><div style={{padding:16,textAlign:"center"}}><p style={{color:"#94a3b8",fontSize:13,marginBottom:12}}>Brak GPS dla celu</p>{destination&&<button onClick={doGeocode} disabled={geoLoading} style={{background:"#9a3412",color:"#fff",border:"none",padding:"10px 20px",borderRadius:10,cursor:"pointer",fontWeight:600,fontSize:13}}>{geoLoading?"⏳":"📍 Znajdź: "+destination}</button>}</div></div>;
if(loading)return<div style={wS.box}><div style={wS.hdr}><span style={{fontSize:20}}>🌤️</span><span style={{fontWeight:700}}>Pogoda — {destination}</span></div><div style={{textAlign:"center",padding:"20px 0",color:"#94a3b8"}}>⏳ Ładowanie...</div></div>;
if(error)return<div style={wS.box}><div style={wS.hdr}><span style={{fontSize:20}}>🌤️</span><span style={{fontWeight:700}}>Pogoda</span></div><p style={{color:"#ef4444",fontSize:13,textAlign:"center",padding:"16px 0"}}>⚠️ {error}</p></div>;
if(!weather)return null;const cur=weather.current,d=weather.daily;const dn=["Nd","Pn","Wt","Śr","Cz","Pt","Sb"];
return(<div style={wS.box}><div style={wS.hdr}><span style={{fontSize:20}}>🌤️</span><span style={{fontWeight:700}}>Pogoda — {destination}</span></div><div style={{display:"flex",alignItems:"center",gap:16,padding:16}}><div style={{fontSize:48}}>{WMO_ICONS[cur.weathercode]||"🌡️"}</div><div><div style={{fontSize:36,fontWeight:700,fontFamily:"'DM Mono',monospace"}}>{Math.round(cur.temperature_2m)}°C</div><div style={{fontSize:14,color:"#475569"}}>{WMO_TEXT[cur.weathercode]||"—"}</div><div style={{fontSize:12,color:"#94a3b8",marginTop:4}}>💧{cur.relative_humidity_2m}% 💨{Math.round(cur.wind_speed_10m)}km/h</div></div></div>
<div style={{display:"flex",overflowX:"auto",gap:4,padding:"4px 8px 12px"}}>{d.time.map((date,i)=>{const dt=new Date(date+"T12:00:00");return(<div key={i} style={{flex:"0 0 auto",width:64,textAlign:"center",padding:"8px 4px",borderRadius:10,background:dark?"#1c1410":"#f8fafc"}}><div style={{fontSize:11,fontWeight:700,color:"#64748b",marginBottom:4}}>{i===0?"Dziś":dn[dt.getDay()]}</div><div style={{fontSize:22}}>{WMO_ICONS[d.weathercode[i]]||"🌡️"}</div><div style={{fontSize:13,fontWeight:700,marginTop:4}}>{Math.round(d.temperature_2m_max[i])}°</div><div style={{fontSize:11,color:"#94a3b8"}}>{Math.round(d.temperature_2m_min[i])}°</div>{d.precipitation_sum[i]>0&&<div style={{fontSize:10,color:"#3b82f6",marginTop:2}}>💧{d.precipitation_sum[i].toFixed(1)}</div>}</div>)})}</div></div>)}
const wSL={box:{background:"#fff",borderRadius:14,border:"1px solid rgba(0,0,0,.06)",marginBottom:12,overflow:"hidden"},hdr:{display:"flex",alignItems:"center",gap:8,padding:"14px 16px",borderBottom:"1px solid #f5e9d8",fontSize:15}};
const wSD={box:{background:"#2a1d14",borderRadius:14,border:"1px solid rgba(255,255,255,.08)",marginBottom:12,overflow:"hidden"},hdr:{display:"flex",alignItems:"center",gap:8,padding:"14px 16px",borderBottom:"1px solid rgba(255,255,255,.06)",fontSize:15,color:"#f1f5f9"}};

/* ═══ DESTINATION DISCOVERY ═══ */
function DestinationDiscovery({destination,lat,lng,onAddPlace}){const dark=useContext(DarkCtx);const[wiki,setWiki]=useState(null);const[pois,setPois]=useState([]);const[loading,setLoading]=useState(false);const[dtab,setDtab]=useState("info");
useEffect(()=>{if(!destination)return;setLoading(true);
fetch(`https://pl.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(destination)}`).then(r=>r.ok?r.json():null).then(d=>{if(d&&d.extract)setWiki(d)}).catch(()=>{fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(destination)}`).then(r=>r.ok?r.json():null).then(d=>{if(d&&d.extract)setWiki(d)}).catch(()=>{})});
if(lat&&lng){fetch(`https://api.opentripmap.com/0.1/en/places/radius?radius=10000&lon=${lng}&lat=${lat}&kinds=interesting_places,museums,historic,natural,architecture&format=json&limit=12&apikey=5ae2e3f221c38a28845f05b6aeb0c3dfb6c68df20b0b8c4c12bf20d8`).then(r=>r.json()).then(data=>{if(Array.isArray(data))setPois(data.filter(p=>p.name&&p.name.trim()))}).catch(()=>{})}
setLoading(false)},[destination,lat,lng]);
if(!destination)return null;
return(<div style={{background:dark?"#2a1d14":"#fff",borderRadius:14,border:dark?"1px solid rgba(255,255,255,.08)":"1px solid rgba(0,0,0,.06)",marginBottom:12,overflow:"hidden"}}>
<div style={{display:"flex",borderBottom:dark?"1px solid rgba(255,255,255,.06)":"1px solid #f1f5f9"}}>{[["info","ℹ️ O miejscu"],["pois","🏛️ Atrakcje"]].map(([k,l])=><button key={k} onClick={()=>setDtab(k)} style={{flex:1,padding:"12px 8px",background:"none",border:"none",borderBottom:dtab===k?"2px solid #9a3412":"2px solid transparent",cursor:"pointer",fontFamily:"'DM Sans',sans-serif",fontSize:13,fontWeight:dtab===k?700:500,color:dtab===k?"#9a3412":"#94a3b8"}}>{l}</button>)}</div>
{dtab==="info"&&<div style={{padding:16}}>{wiki?<>{wiki.thumbnail&&<img src={wiki.thumbnail.source} alt="" style={{width:"100%",height:160,objectFit:"cover",borderRadius:10,marginBottom:12}}/>}<h4 style={{fontSize:16,fontWeight:700,fontFamily:"'Playfair Display',serif",marginBottom:8}}>{wiki.title}</h4><p style={{fontSize:14,color:"#475569",lineHeight:1.7}}>{wiki.extract}</p>{wiki.content_urls&&<a href={wiki.content_urls.desktop.page} target="_blank" rel="noreferrer" style={{display:"inline-block",marginTop:8,fontSize:12,color:"#3b82f6",fontWeight:600}}>📖 Wikipedia →</a>}</>:<div style={{textAlign:"center",padding:"20px 0",color:"#94a3b8",fontSize:13}}>{loading?"⏳ Szukam...":"Brak informacji"}</div>}</div>}
{dtab==="pois"&&<div style={{padding:12,maxHeight:300,overflowY:"auto"}}>{pois.length>0?pois.map((p,i)=>(<div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 12px",background:i%2===0?"#f8fafc":"#fff",borderRadius:8,marginBottom:4}}><div style={{flex:1}}><div style={{fontSize:14,fontWeight:600}}>{p.name}</div>{p.kinds&&<div style={{fontSize:11,color:"#94a3b8",marginTop:2}}>{p.kinds.split(",").slice(0,3).map(k=>k.replace(/_/g," ")).join(" • ")}</div>}</div>{p.point&&onAddPlace&&<button onClick={()=>onAddPlace({id:uid(),name:p.name,description:p.kinds?p.kinds.split(",").slice(0,2).map(k=>k.replace(/_/g," ")).join(", "):"",priority:"medium",visited:false,lat:p.point.lat,lng:p.point.lon})} style={{background:"#10b981",color:"#fff",border:"none",padding:"4px 10px",borderRadius:6,cursor:"pointer",fontSize:11,fontWeight:600,flexShrink:0,marginLeft:8}}>+ Dodaj</button>}</div>)):<div style={{textAlign:"center",padding:"20px 0",color:"#94a3b8",fontSize:13}}>Brak atrakcji w bazie</div>}</div>}
</div>)}

/* ═══ CURRENCY ═══ */
function CurrencyConverter({baseCurrency}){const dark=useContext(DarkCtx);const s=dark?sDark:sL;const[amount,setAmount]=useState("100");const[from,setFrom]=useState(baseCurrency||"PLN");const[to,setTo]=useState(baseCurrency==="EUR"?"PLN":"EUR");const[rate,setRate]=useState(null);const[loading,setLoading]=useState(false);
const convert=async()=>{if(!amount)return;setLoading(true);try{const r=await fetch(`https://api.frankfurter.dev/v1/latest?amount=${amount}&from=${from}&to=${to}`);const d=await r.json();if(d.rates&&d.rates[to])setRate(d.rates[to]);else setRate(null)}catch{setRate(null)}setLoading(false)};
useEffect(()=>{if(amount&&from!==to)convert()},[from,to]);
return(<div style={{background:dark?"#2a1d14":"#fff",borderRadius:14,padding:16,border:dark?"1px solid rgba(255,255,255,.08)":"1px solid rgba(0,0,0,.06)",marginBottom:16}}><h3 style={{fontSize:15,fontWeight:700,marginBottom:12,color:dark?"#f1f5f9":"#1e293b"}}>💱 Przelicznik walut</h3>
<div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}><input type="number" value={amount} onChange={e=>setAmount(e.target.value)} style={{...s.inp,flex:1,minWidth:80,marginBottom:0}} placeholder="Kwota"/><select value={from} onChange={e=>setFrom(e.target.value)} style={{...s.inp,width:80,flex:"none",marginBottom:0}}>{CURRENCIES.map(c=><option key={c}>{c}</option>)}</select><button onClick={()=>{const t=from;setFrom(to);setTo(t)}} style={{background:"none",border:"none",fontSize:20,cursor:"pointer",padding:4}}>⇄</button><select value={to} onChange={e=>setTo(e.target.value)} style={{...s.inp,width:80,flex:"none",marginBottom:0}}>{CURRENCIES.map(c=><option key={c}>{c}</option>)}</select><button onClick={convert} disabled={loading||from===to} style={{background:"#9a3412",color:"#fff",border:"none",padding:"10px 16px",borderRadius:10,cursor:"pointer",fontWeight:600,fontSize:13}}>{loading?"⏳":"Przelicz"}</button></div>
{rate!==null&&<div style={{marginTop:12,textAlign:"center",padding:12,background:dark?"#1c1410":"#fff7ed",borderRadius:10}}><div style={{fontSize:14,color:"#64748b"}}>{amount} {from} =</div><div style={{fontSize:28,fontWeight:700,fontFamily:"'DM Mono',monospace",color:dark?"#fdba74":"#9a3412"}}>{rate.toFixed(2)} {to}</div></div>}</div>)}

/* ═══ PHOTO ═══ */
function PhotoUpload({photos,onChange}){const fileRef=useRef(null);const[uploading,setUploading]=useState(false);const handleFiles=async(e)=>{const files=Array.from(e.target.files);if(!files.length)return;setUploading(true);const np=[];for(const f of files.slice(0,5)){if(!f.type.startsWith("image/"))continue;np.push({id:uid(),data:await compressImage(f),name:f.name})}onChange([...(photos||[]),...np]);setUploading(false);if(fileRef.current)fileRef.current.value=""};
return(<div><div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:8}}>{(photos||[]).map(p=><div key={p.id} style={{position:"relative",width:80,height:80,borderRadius:10,overflow:"hidden",border:"2px solid #ecdfc9"}}><img src={p.data} style={{width:"100%",height:"100%",objectFit:"cover"}} alt=""/><button onClick={()=>onChange(photos.filter(x=>x.id!==p.id))} style={{position:"absolute",top:2,right:2,width:20,height:20,borderRadius:"50%",background:"rgba(0,0,0,.6)",color:"#fff",border:"none",cursor:"pointer",fontSize:12,display:"flex",alignItems:"center",justifyContent:"center"}}>✕</button></div>)}<button onClick={()=>fileRef.current&&fileRef.current.click()} disabled={uploading} style={{width:80,height:80,borderRadius:10,border:"2px dashed #dcc9ab",background:"#f8fafc",cursor:"pointer",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",fontSize:10,color:"#94a3b8",fontWeight:600}}>{uploading?"⏳":<>📷<span style={{marginTop:2}}>Dodaj</span></>}</button></div><input ref={fileRef} type="file" accept="image/*" multiple onChange={handleFiles} style={{display:"none"}}/></div>)}

/* ═══ MAP ═══ */
function TripMap({trip,onAddPlace}){const containerRef=useRef(null);const mapRef=useRef(null);const markersRef=useRef(null);const clickMkRef=useRef(null);const myLocRef=useRef(null);const[ready,setReady]=useState(false);const[query,setQuery]=useState("");const[results,setResults]=useState([]);const[searching,setSearching]=useState(false);const[clickPos,setClickPos]=useState(null);const[newName,setNewName]=useState("");const watchRef=useRef(null);const orientHandler=useRef(null);const[gpsLoading,setGpsLoading]=useState(false);const[gpsError,setGpsError]=useState("");const[tracking,setTracking]=useState(false);
useEffect(()=>{if(window.L){setReady(true);return}const css=document.createElement("link");css.rel="stylesheet";css.href="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css";document.head.appendChild(css);const js=document.createElement("script");js.src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js";js.onload=()=>setReady(true);document.head.appendChild(js)},[]);
useEffect(()=>{if(!ready||!containerRef.current||mapRef.current)return;const L=window.L;const map=L.map(containerRef.current,{zoomControl:false}).setView([52,19],6);L.control.zoom({position:"bottomright"}).addTo(map);L.tileLayer("https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png",{attribution:'© OSM',maxZoom:19}).addTo(map);markersRef.current=L.layerGroup().addTo(map);map.on("click",e=>{setClickPos({lat:e.latlng.lat,lng:e.latlng.lng});setNewName("")});mapRef.current=map;if(trip.destLat&&trip.destLng)map.setView([trip.destLat,trip.destLng],10);else if(trip.destination)fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(trip.destination)}&limit=1`).then(r=>r.json()).then(d=>{if(d[0]&&mapRef.current)mapRef.current.setView([+d[0].lat,+d[0].lon],10)}).catch(()=>{});return()=>{if(mapRef.current){try{mapRef.current.remove()}catch(e){}}mapRef.current=null;markersRef.current=null}},[ready]);
useEffect(()=>{if(!mapRef.current||!window.L||!markersRef.current)return;const L=window.L;try{markersRef.current.clearLayers()}catch(e){return}const geo=trip.places.filter(p=>p.lat&&p.lng);geo.forEach(p=>{const c=p.visited?"#94a3b8":(PRI_COLORS[p.priority]||"#9a3412");L.marker([p.lat,p.lng],{icon:L.divIcon({className:"",iconSize:[0,0],html:`<div style="width:34px;height:34px;border-radius:50%;background:${c};border:3px solid #fff;box-shadow:0 2px 10px rgba(0,0,0,.35);display:flex;align-items:center;justify-content:center;font-size:15px;color:#fff;font-weight:700;transform:translate(-17px,-17px);${p.visited?"opacity:.55;":""}">${p.visited?"✓":"📍"}</div>`})}).bindPopup(`<div style="font-family:sans-serif"><strong>${p.name}</strong>${p.description?`<p style="color:#666;font-size:12px;margin:4px 0 0">${p.description}</p>`:""}</div>`).addTo(markersRef.current)});if(geo.length>1)try{mapRef.current.fitBounds(L.latLngBounds(geo.map(p=>[p.lat,p.lng])).pad(.25))}catch(e){}else if(geo.length===1)try{mapRef.current.setView([geo[0].lat,geo[0].lng],13)}catch(e){}},[trip.places,ready]);
useEffect(()=>{if(!mapRef.current||!window.L)return;if(clickMkRef.current){try{mapRef.current.removeLayer(clickMkRef.current)}catch(e){};clickMkRef.current=null}if(!clickPos)return;clickMkRef.current=window.L.marker([clickPos.lat,clickPos.lng],{icon:window.L.divIcon({className:"",iconSize:[0,0],html:`<div style="width:22px;height:22px;border-radius:50%;background:#ef4444;border:3px solid #fff;box-shadow:0 2px 10px rgba(239,68,68,.5);transform:translate(-11px,-11px)"></div>`})}).addTo(mapRef.current)},[clickPos]);
const updateLocMarker=(la,lo,hdg)=>{if(!mapRef.current||!window.L)return;if(myLocRef.current){try{mapRef.current.removeLayer(myLocRef.current)}catch(e){}}const arrowHtml=hdg!=null?`<div style="position:absolute;top:-16px;left:50%;transform:translateX(-50%) rotate(${hdg}deg);width:0;height:0;border-left:6px solid transparent;border-right:6px solid transparent;border-bottom:16px solid #3b82f6;filter:drop-shadow(0 1px 3px rgba(0,0,0,.4))"></div>`:"";myLocRef.current=window.L.marker([la,lo],{icon:window.L.divIcon({className:"",iconSize:[0,0],html:`<div style="position:relative;width:20px;height:20px;border-radius:50%;background:#3b82f6;border:3px solid #fff;box-shadow:0 0 0 8px rgba(59,130,246,.2);transform:translate(-10px,-10px)">${arrowHtml}</div>`})}).bindPopup("📍 Twoja lokalizacja").addTo(mapRef.current)};const goToMyLoc=async()=>{setGpsError("");if(!navigator.geolocation){setGpsError("GPS niedostępny w tej przeglądarce");return}if(watchRef.current){navigator.geolocation.clearWatch(watchRef.current);watchRef.current=null;if(orientHandler.current){window.removeEventListener("deviceorientation",orientHandler.current);orientHandler.current=null}if(myLocRef.current&&mapRef.current){try{mapRef.current.removeLayer(myLocRef.current)}catch(e){}}myLocRef.current=null;setTracking(false);setGpsLoading(false);return}if(navigator.permissions){try{const ps=await navigator.permissions.query({name:"geolocation"});if(ps.state==="denied"){setGpsError("GPS zablokowany. Kliknij 🔒 w pasku adresu → Lokalizacja → Zezwól, potem odśwież.");return}}catch(e){}}setGpsLoading(true);let lastLat=null,lastLon=null,lastHdg=null;orientHandler.current=e=>{const hdg=e.webkitCompassHeading!=null?e.webkitCompassHeading:(e.alpha!=null?((360-e.alpha+360)%360):null);lastHdg=hdg;if(lastLat!=null)updateLocMarker(lastLat,lastLon,hdg)};window.addEventListener("deviceorientation",orientHandler.current,{passive:true});watchRef.current=navigator.geolocation.watchPosition(pos=>{const la=pos.coords.latitude,lo=pos.coords.longitude;if(lastLat==null&&mapRef.current){try{mapRef.current.flyTo([la,lo],15,{duration:1.5})}catch(e){}}lastLat=la;lastLon=lo;const hdg=pos.coords.heading!=null&&!isNaN(pos.coords.heading)?pos.coords.heading:lastHdg;updateLocMarker(la,lo,hdg);setGpsLoading(false);setTracking(true)},err=>{setGpsLoading(false);setTracking(false);setGpsError(err.code===1?"GPS zablokowany — kliknij 🔒 w adresie → Lokalizacja → Zezwól":err.code===3?"GPS timeout — spróbuj ponownie":"Nie można ustalić pozycji");if(watchRef.current){navigator.geolocation.clearWatch(watchRef.current);watchRef.current=null}},{enableHighAccuracy:true,timeout:15000,maximumAge:3000})};const doSearch=async()=>{if(!query.trim())return;setSearching(true);setResults([]);try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=5&addressdetails=1`,{headers:{"Accept-Language":"pl"}});setResults(await r.json())}catch{setResults([])}setSearching(false)};const flyTo=(lat,lng)=>{if(mapRef.current)try{mapRef.current.flyTo([lat,lng],14,{duration:1})}catch(e){}};const addFromClick=()=>{if(!clickPos||!newName.trim())return;onAddPlace({id:uid(),name:newName.trim(),description:"",priority:"medium",visited:false,lat:clickPos.lat,lng:clickPos.lng});setClickPos(null);setNewName("")};
if(!ready)return<div style={{display:"flex",alignItems:"center",justifyContent:"center",height:400,color:"#94a3b8"}}><div style={{textAlign:"center"}}><div style={{fontSize:48,marginBottom:8}}>🗺️</div>Ładowanie mapy...</div></div>;const geoCount=trip.places.filter(p=>p.lat).length;
return(<div style={{position:"relative"}}><div style={ms.sw}><div style={ms.sr}><input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==="Enter"&&doSearch()} placeholder="🔍 Szukaj miejsca..." style={ms.si}/><button onClick={doSearch} disabled={searching} style={ms.sb}>{searching?"⏳":"Szukaj"}</button></div>{results.length>0&&<div style={ms.dd}>{results.map((r,i)=>(<div key={i} style={ms.di}><div onClick={()=>{flyTo(+r.lat,+r.lon);setResults([]);setQuery(r.display_name.split(",")[0])}} style={{flex:1,cursor:"pointer"}}><div style={{fontWeight:600,fontSize:14}}>{r.display_name.split(",")[0]}</div><div style={{fontSize:12,color:"#94a3b8",marginTop:2}}>{r.display_name.slice(0,90)}</div></div><button onClick={()=>{onAddPlace({id:uid(),name:r.display_name.split(",")[0],description:r.display_name.split(",").slice(1,3).join(",").trim(),priority:"medium",visited:false,lat:+r.lat,lng:+r.lon});flyTo(+r.lat,+r.lon);setResults([]);setQuery("")}} style={ms.da}>+ Dodaj</button></div>))}</div>}</div>
<div ref={containerRef} style={ms.mc}/>{clickPos&&<div style={ms.cb}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}><span style={{fontSize:14,fontWeight:700}}>📍 Nowe miejsce</span><button onClick={()=>setClickPos(null)} style={{background:"none",border:"none",fontSize:16,cursor:"pointer",color:"#94a3b8"}}>✕</button></div><div style={{fontSize:11,color:"#94a3b8",marginBottom:8,fontFamily:"monospace"}}>{clickPos.lat.toFixed(5)}, {clickPos.lng.toFixed(5)}</div><input value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==="Enter"&&addFromClick()} placeholder="Wpisz nazwę..." style={ms.ci} autoFocus/><button onClick={addFromClick} disabled={!newName.trim()} style={{...ms.ca,opacity:newName.trim()?1:.5}}>Dodaj do listy</button></div>}
<button onClick={goToMyLoc} disabled={gpsLoading} title={tracking?"Zatrzymaj śledzenie GPS":"Włącz śledzenie GPS"} style={{position:"absolute",bottom:60,right:12,zIndex:6,background:tracking?"#eff6ff":"#fff",border:tracking?"2px solid #3b82f6":"2px solid transparent",borderRadius:12,padding:"9px 14px",cursor:gpsLoading?"default":"pointer",boxShadow:"0 2px 12px rgba(0,0,0,.18)",fontSize:13,fontWeight:700,color:gpsLoading?"#94a3b8":tracking?"#1d4ed8":"#3b82f6",display:"flex",alignItems:"center",gap:5,minWidth:130,justifyContent:"center"}}>{gpsLoading?"⏳ Szukam...":tracking?"🔵 GPS aktywny":"📍 Tu jestem"}</button>{gpsError&&<div style={{position:"absolute",bottom:110,right:12,zIndex:6,background:"#fef2f2",border:"1px solid #fecaca",borderRadius:10,padding:"10px 14px",fontSize:12,color:"#dc2626",fontWeight:600,maxWidth:240,lineHeight:1.5}}>{gpsError}</div>}<div style={ms.lg}>{[["#ef4444","Wysoki"],["#f59e0b","Średni"],["#22c55e","Niski"],["#94a3b8","✓"]].map(([c,l])=><div key={l} style={ms.li}><div style={{...ms.ld,background:c}}/>{l}</div>)}</div><div style={ms.ct}>📍 {geoCount}/{trip.places.length}</div>{geoCount===0&&<div style={ms.ht}>Kliknij na mapę lub szukaj</div>}</div>)}

function MiniMap({trip}){const ref=useRef(null);const mapInst=useRef(null);const[mapReady,setMapReady]=useState(false);useEffect(()=>{if(window.L)setMapReady(true);else{const c=setInterval(()=>{if(window.L){setMapReady(true);clearInterval(c)}},200);return()=>clearInterval(c)}},[]);useEffect(()=>{if(!mapReady||!ref.current||mapInst.current)return;const geo=trip.places.filter(p=>p.lat&&p.lng);if(!geo.length)return;try{const L=window.L;const map=L.map(ref.current,{zoomControl:false,attributionControl:false,dragging:false,scrollWheelZoom:false,touchZoom:false,doubleClickZoom:false});L.tileLayer("https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png",{maxZoom:19}).addTo(map);geo.forEach(p=>L.marker([p.lat,p.lng],{icon:L.divIcon({className:"",iconSize:[0,0],html:`<div style="width:12px;height:12px;border-radius:50%;background:${PRI_COLORS[p.priority]||"#9a3412"};border:2px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.3);transform:translate(-6px,-6px)"></div>`})}).addTo(map));if(geo.length>1)map.fitBounds(L.latLngBounds(geo.map(p=>[p.lat,p.lng])).pad(.3));else map.setView([geo[0].lat,geo[0].lng],12);mapInst.current=map}catch(e){}return()=>{if(mapInst.current){try{mapInst.current.remove()}catch(e){}}mapInst.current=null}},[mapReady,trip.places]);return<div ref={ref} style={{width:"100%",height:"100%"}}/>}

/* ═══ PDF ═══ */
function exportPDF(trip){const days=trip.startDate&&trip.endDate?Math.ceil((new Date(trip.endDate)-new Date(trip.startDate))/864e5)+1:0;const spent=trip.expenses.reduce((s,e)=>s+e.amount,0);const byCat=CATEGORIES.map(c=>({c,t:trip.expenses.filter(e=>e.category===c).reduce((s,e)=>s+e.amount,0)})).filter(x=>x.t>0);
const html=`<!DOCTYPE html><html><head><meta charset="utf-8"><title>${trip.name}</title><style>body{font-family:Arial,sans-serif;max-width:700px;margin:0 auto;padding:24px;color:#1e293b;font-size:13px}h1{font-size:24px}h2{font-size:16px;margin-top:24px;border-bottom:2px solid #9a3412;padding-bottom:4px;color:#9a3412}table{width:100%;border-collapse:collapse;margin:8px 0}th,td{border:1px solid #ecdfc9;padding:8px;text-align:left;font-size:12px}th{background:#fdf3e7}@media print{body{padding:12px}}</style></head><body><h1>${trip.coverEmoji} ${trip.name}</h1><div style="color:#64748b;margin-bottom:20px">${trip.destination||""}${trip.startDate?` • ${trip.startDate} → ${trip.endDate}`:""}</div>${trip.places.length?`<h2>📍 Miejsca</h2><table><tr><th>Nazwa</th><th>Priorytet</th><th>Status</th></tr>${trip.places.map(p=>`<tr><td>${p.name}</td><td>${p.priority}</td><td>${p.visited?"✅":"⬜"}</td></tr>`).join("")}</table>`:""}${trip.itinerary.length?`<h2>🗓️ Plan dnia</h2>${trip.itinerary.map(d=>`<h3>${d.day}${d.title?" — "+d.title:""}</h3><table>${d.items.filter(i=>i.activity).map(i=>`<tr><td>${i.time}</td><td>${i.activity}</td></tr>`).join("")}</table>`).join("")}`:""}${byCat.length?`<h2>💰 Budżet (${spent.toFixed(2)} ${trip.currency})</h2><table>${byCat.map(({c,t})=>`<tr><td>${c}</td><td>${t.toFixed(2)}</td><td>${(t/spent*100).toFixed(0)}%</td></tr>`).join("")}</table>`:""}${trip.packing&&trip.packing.length?`<h2>🎒 Pakowanie</h2><table>${trip.packing.map(p=>`<tr><td>${p.name}</td><td>${p.packed?"✅":"⬜"}</td></tr>`).join("")}</table>`:""}${trip.notes.length?`<h2>📝 Notatki</h2>${trip.notes.map(n=>`<div style="margin:12px 0;padding:12px;background:#f8fafc;border-radius:8px"><strong>${n.title}</strong><p>${n.content}</p></div>`).join("")}`:""}<div style="margin-top:32px;text-align:center;color:#94a3b8;font-size:11px">🧭 Voyager</div></body></html>`;
const w=window.open("","_blank");if(w){w.document.write(html);w.document.close();setTimeout(()=>w.print(),500)}else{const blob=new Blob([html],{type:"text/html;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=(trip.name||"voyager")+".html";document.body.appendChild(a);a.click();document.body.removeChild(a);setTimeout(()=>URL.revokeObjectURL(url),1000)}}

/* ═══ AI CHAT (GEMINI) ═══ */
function AIChat({trip,onClose,onAddPlaces,onUpdatePlace,onAddToItinerary}){const dark=useContext(DarkCtx);const s=dark?sDark:sL;const[msgs,setMsgs]=useState([{role:"assistant",text:`Cześć! 🌍 Jestem asystentem podróży${trip?.destination?` do ${trip.destination}`:""}.\n\nMogę pomóc z:\n🏛️ Ciekawostki i atrakcje\n🍽️ Restauracje i jedzenie\n🗓️ Plan dnia\n💡 Porady\n\nO co chcesz zapytać?`}]);const[input,setInput]=useState("");const[loading,setLoading]=useState(false);const[apiKey,setApiKey]=useState(()=>loadApiKey());const[showSetup,setShowSetup]=useState(()=>!loadApiKey());const[saved,setSaved]=useState({});const endRef=useRef(null);const[panelH,setPanelH]=useState("85vh");useEffect(()=>{const upd=()=>{const vp=window.visualViewport;if(!vp)return;const maxH=window.innerHeight*0.85;setPanelH(Math.min(maxH,vp.height-20)+"px")};window.visualViewport?.addEventListener("resize",upd);upd();return()=>window.visualViewport?.removeEventListener("resize",upd)},[]);
const stripEmoji=s=>s.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE00}-\u{FE0F}\u{1F000}-\u{1F02F}\u{1F0A0}-\u{1F0FF}]/gu,"").replace(/[✀-➿]/g,"").trim();const addAsPlace=(text,idx)=>{const lines=text.split("\n").filter(l=>l.trim()&&l.length>4);const places=[];lines.forEach(l=>{let cleaned=l.replace(/^[\d\.\)\-\*•►▸]+\s*/,"").replace(/\*\*/g,"").trim();if(!cleaned||cleaned.length<3)return;if(/^(oto |tutaj |polecam|mogę |cześć|plan |podsumow|oczywiście|jasne|chętnie|kontekst|poniżej|oto lista|lista)/i.test(cleaned))return;const emojiClean=stripEmoji(cleaned);if(emojiClean.length<2)return;let name,desc;const dashMatch=cleaned.match(/^(.+?)\s*[—–\-:]\s*(.+)/);if(dashMatch){name=stripEmoji(dashMatch[1]);desc=dashMatch[2].trim()}else{name=emojiClean.slice(0,60);desc=""}name=name.replace(/^[,.\s]+|[,.\s]+$/g,"").trim();if(name.length<2||name.length>70)return;places.push({id:uid(),name,description:desc.slice(0,250)||"",address:"",priority:"medium",visited:false,lat:null,lng:null})});if(places.length===0){const first=lines[0]||text.slice(0,60);places.push({id:uid(),name:stripEmoji(first).slice(0,60)||"Miejsce z AI",description:"",address:"",priority:"medium",visited:false,lat:null,lng:null})}onAddPlaces(places);setSaved(p=>({...p,[`p${idx}`]:true}));geocodePlaces(places)};const geoSearch=async(query,lat,lng)=>{let url=`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=3&addressdetails=1`;if(lat&&lng){const vb=`${lng-0.5},${lat+0.5},${lng+0.5},${lat-0.5}`;url+=`&viewbox=${vb}&bounded=1`}const r=await fetch(url,{headers:{"Accept-Language":"pl"}});return await r.json()};const geocodePlaces=async(places)=>{const dest=trip?.destination||"";const dlat=trip?.destLat;const dlng=trip?.destLng;for(let i=0;i<places.length;i++){const p=places[i];const cleanName=p.name.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu,"").replace(/["""„()]/g,"").replace(/\s+/g," ").trim();if(!cleanName||cleanName.length<2)continue;try{let found=false;const searches=[{q:`${cleanName}, ${dest}`,useBounds:true},{q:cleanName,useBounds:true},{q:`${cleanName}, ${dest}`,useBounds:false}];for(const s of searches){if(found)break;const d=await geoSearch(s.q,s.useBounds?dlat:null,s.useBounds?dlng:null);if(d&&d[0]){onUpdatePlace(p.id,+d[0].lat,+d[0].lon,d[0].display_name||"");found=true;break}if(!found)await new Promise(ok=>setTimeout(ok,700))}}catch{}await new Promise(ok=>setTimeout(ok,300))}};
const addAsItinerary=(text,idx)=>{const lines=text.split("\n").filter(l=>l.trim()&&l.length>3);const items=lines.slice(0,8).map((l,i)=>{const timeMatch=l.match(/(\d{1,2})[:.:](\d{2})/);const time=timeMatch?timeMatch[1].padStart(2,"0")+":"+timeMatch[2]:String(8+i).padStart(2,"0")+":00";const activity=l.replace(/^\s*\d{1,2}[:.]\d{2}\s*[-–:.]\s*/,"").replace(/^[\-\*\•\d\.\)]\s*/,"").trim();return{time,activity:activity||l.trim()}});const day=trip.startDate||new Date().toISOString().split("T")[0];onAddToItinerary({id:uid(),day,title:"Plan z AI",items:items.filter(i=>i.activity)});setSaved(p=>({...p,[`i${idx}`]:true}))};
useEffect(()=>{if(endRef.current)endRef.current.scrollIntoView({behavior:"smooth"})},[msgs]);
const send=async()=>{if(!input.trim()||loading)return;if(!apiKey){setShowSetup(true);return}const txt=input.trim();setInput("");setMsgs(m=>[...m,{role:"user",text:txt}]);setLoading(true);
try{const days2=trip?.startDate&&trip?.endDate?Math.ceil((new Date(trip.endDate)-new Date(trip.startDate))/864e5)+1:0;const ctx=trip?`[Kontekst podróży] Cel: ${trip.destination||"?"} | Daty: ${trip.startDate||"?"}–${trip.endDate||"?"} (${days2||"?"} dni) | Waluta: ${trip.currency}${trip.places.length?` | Dodane miejsca: ${trip.places.map(p=>p.name).join(", ")}`:""}.`:"";
const history=msgs.filter(m=>m.text).map(m=>({role:m.role==="assistant"?"assistant":"user",content:m.text}));
const res=await fetch("https://api.groq.com/openai/v1/chat/completions",{method:"POST",headers:{"Content-Type":"application/json","Authorization":`Bearer ${apiKey}`},body:JSON.stringify({model:"llama-3.3-70b-versatile",messages:[{role:"system",content:`Jesteś ekspertem od podróży, odpowiadasz WYŁĄCZNIE po polsku. Zasady formatowania:\n1. Lista miejsc/atrakcji: każde w OSOBNEJ LINII w formacie "Oficjalna nazwa — opis (cena lub godziny)"\n2. Plan dnia: każda linia "HH:MM — aktywność"\n3. Używaj wyłącznie OFICJALNYCH nazw geograficznych (np. "Colosseum", "Marienplatz", "Sagrada Família")\n4. Odpowiedź max 10 pozycji, bez wstępów i podsumowań\n5. Dodawaj emoji przed każdą pozycją\n6. Przy miejscach podaj praktyczną informację (cena biletu, godz. otwarcia, adres)\n${ctx}`},...history,{role:"user",content:txt}],temperature:0.7,max_tokens:1200})});
const data=await res.json();const reply=data.choices?.[0]?.message?.content;
if(reply)setMsgs(m=>[...m,{role:"assistant",text:reply}]);else setMsgs(m=>[...m,{role:"assistant",text:"⚠️ Sprawdź klucz API."}])}catch(e){setMsgs(m=>[...m,{role:"assistant",text:"⚠️ Błąd: "+e.message}])}setLoading(false)};
const quickQ=[`Co warto zobaczyć w ${trip?.destination||"okolicy"}?`,`Najlepsze restauracje w ${trip?.destination||"okolicy"}`,`Ciekawostki o ${trip?.destination||"tym miejscu"}`,`Plan na 1 dzień w ${trip?.destination||"okolicy"}`];
return(<div style={s.aiO}><div style={{...s.aiP,height:panelH}}><div style={s.aiH}><span style={{fontSize:18}}>🤖 Asystent AI</span><button onClick={onClose} style={s.clB}>✕</button></div>
{showSetup&&<div style={{padding:16,background:"#fffbeb",borderBottom:"1px solid #fde68a"}}><p style={{fontSize:13,color:"#92400e",marginBottom:8}}>🔑 Podaj klucz Groq API (darmowy):</p><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer" style={{fontSize:12,color:"#3b82f6",fontWeight:600}}>→ Pobierz klucz na console.groq.com</a><div style={{display:"flex",gap:6,marginTop:8}}><input value={apiKey} onChange={e=>setApiKey(e.target.value)} placeholder="gsk_..." style={{...s.aiI,flex:1}}/><button onClick={()=>{saveApiKey(apiKey);setShowSetup(false)}} style={{background:"#9a3412",color:"#fff",border:"none",padding:"8px 16px",borderRadius:10,cursor:"pointer",fontSize:13,fontWeight:600}}>Zapisz</button></div></div>}
<div style={s.aiM}>{msgs.map((m,i)=><div key={i} style={{maxWidth:"85%",alignSelf:m.role==="user"?"flex-end":"flex-start"}}><div style={{...s.bbl,...(m.role==="user"?s.uB:s.aB)}}><div style={{whiteSpace:"pre-wrap",lineHeight:1.6}}>{m.text}</div></div>{m.role==="assistant"&&i>0&&<div style={{display:"flex",gap:6,marginTop:4,flexWrap:"wrap"}}><button onClick={()=>addAsPlace(m.text,i)} disabled={saved[`p${i}`]} style={{background:saved[`p${i}`]?"#dcfce7":"#fff7ed",border:"1px solid "+(saved[`p${i}`]?"#86efac":"#fed7aa"),borderRadius:16,padding:"4px 10px",fontSize:11,color:saved[`p${i}`]?"#16a34a":"#9a3412",cursor:"pointer",fontFamily:"'DM Sans',sans-serif",fontWeight:600}}>{saved[`p${i}`]?"✅ Dodano do miejsc":"📍 Dodaj miejsca"}</button><button onClick={()=>addAsItinerary(m.text,i)} disabled={saved[`i${i}`]} style={{background:saved[`i${i}`]?"#dcfce7":"#fffbeb",border:"1px solid "+(saved[`i${i}`]?"#86efac":"#fde68a"),borderRadius:16,padding:"4px 10px",fontSize:11,color:saved[`i${i}`]?"#16a34a":"#92400e",cursor:"pointer",fontFamily:"'DM Sans',sans-serif",fontWeight:600}}>{saved[`i${i}`]?"✅ Dodano do planu":"🗓️ Dodaj plan dnia"}</button></div>}</div>)}{loading&&<div style={{...s.bbl,...s.aB,color:"#94a3b8"}}>✨ Myślę...</div>}{msgs.length<=1&&!loading&&<div style={{display:"flex",flexWrap:"wrap",gap:6,marginTop:8}}>{quickQ.map((q,i)=><button key={i} onClick={()=>setInput(q)} style={{background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:20,padding:"8px 14px",fontSize:12,color:"#9a3412",cursor:"pointer",fontFamily:"'DM Sans',sans-serif",fontWeight:500}}>{q}</button>)}</div>}<div ref={endRef}/></div>
<div style={{...s.aiR,paddingBottom:"calc(12px + env(safe-area-inset-bottom, 0px))"}}><button onClick={()=>setShowSetup(!showSetup)} style={{background:"none",border:"none",fontSize:16,cursor:"pointer",padding:4,opacity:.5}}>⚙️</button><input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&send()} placeholder={apiKey?"Zapytaj...":"Ustaw klucz API ⚙️"} style={{...s.aiI,flex:1}}/><button onClick={send} disabled={loading} style={s.snB}>➤</button></div></div></div>)}

/* ═══ MAIN APP ═══ */
export default function TravelPlanner(){const[trips,setTrips]=useState(()=>loadTrips());const[active,setActive]=useState(null);const[tab,setTab]=useState("Przegląd");const[form,setForm]=useState(null);const[edit,setEdit]=useState(null);const[showAI,setShowAI]=useState(false);const[darkMode,setDarkMode]=useState(()=>loadDark());const[packInput,setPackInput]=useState("");const[deleteConfirm,setDeleteConfirm]=useState(false);const[clearPackConfirm,setClearPackConfirm]=useState(false);const[geocodingIds,setGeocodingIds]=useState({});const[geocodeErrors,setGeocodeErrors]=useState({});
const s=darkMode?sDark:sL;
useEffect(()=>{saveTrips(trips)},[trips]);useEffect(()=>{saveDark(darkMode)},[darkMode]);const trip=trips.find(t=>t.id===active);const upTrip=useCallback((u)=>setTrips(p=>p.map(t=>t.id===active?{...t,...u}:t)),[active]);

const TripForm=()=>{const[f,sF]=useState(edit||defaultTrip());const em=["✈️","🏖️","🏔️","🌍","🗼","🏛️","🎡","🚗","🛳️","🌴","🏕️","🎿"];const[geoStatus,setGeoStatus]=useState(f.destLat?"✅":"");
const geocode=async(dest)=>{if(!dest.trim())return;setGeoStatus("⏳");try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(dest)}&limit=1`);const d=await r.json();if(d[0]){sF(prev=>({...prev,destLat:+d[0].lat,destLng:+d[0].lon}));setGeoStatus("✅")}else setGeoStatus("❌")}catch{setGeoStatus("❌")}};
return<div style={s.modal}><div style={s.mc}><h3 style={s.fT}>{edit?"Edytuj":"Nowa"} podróż ✈️</h3><div style={s.eR}>{em.map(e=><button key={e} onClick={()=>sF({...f,coverEmoji:e})} style={{...s.eB,...(f.coverEmoji===e?s.eBA:{})}}>{e}</button>)}</div><input placeholder="Nazwa podróży" value={f.name} onChange={e=>sF({...f,name:e.target.value})} style={s.inp}/><div style={{position:"relative"}}><input placeholder="Cel (miasto/kraj)" value={f.destination} onChange={e=>{sF({...f,destination:e.target.value});setGeoStatus("")}} onBlur={e=>geocode(e.target.value)} style={s.inp}/>{geoStatus&&<div style={{position:"absolute",right:12,top:12,fontSize:13}}>{geoStatus}</div>}</div><div style={s.row}><input type="date" value={f.startDate} onChange={e=>sF({...f,startDate:e.target.value})} style={{...s.inp,flex:1}}/><input type="date" value={f.endDate} onChange={e=>sF({...f,endDate:e.target.value})} style={{...s.inp,flex:1}}/></div><select value={f.currency} onChange={e=>sF({...f,currency:e.target.value})} style={s.inp}>{CURRENCIES.map(c=><option key={c}>{c}</option>)}</select><div style={s.row}><button onClick={()=>{setForm(null);setEdit(null)}} className="vy-btn" style={s.b2}>Anuluj</button><button onClick={()=>{if(!f.name)return;if(edit)setTrips(p=>p.map(t=>t.id===f.id?f:t));else{setTrips(p=>[...p,f]);setActive(f.id)}setForm(null);setEdit(null)}} className="vy-btn" style={s.b1}>{edit?"Zapisz":"Utwórz"}</button></div></div></div>};

const PlaceForm=()=>{const[f,sF]=useState(edit||{id:uid(),name:"",description:"",priority:"medium",visited:false,lat:null,lng:null});const[gq,sGq]=useState("");const[gr,sGr]=useState([]);const[gl,sGl]=useState(false);const geo=async()=>{if(!gq.trim())return;sGl(true);try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(gq)}&limit=4`);sGr(await r.json())}catch{}sGl(false)};
return<div style={s.modal}><div style={s.mc}><h3 style={s.fT}>📍 {edit?"Edytuj":"Dodaj"} miejsce</h3><input placeholder="Nazwa" value={f.name} onChange={e=>sF({...f,name:e.target.value})} style={s.inp}/><textarea placeholder="Opis" value={f.description} onChange={e=>sF({...f,description:e.target.value})} style={{...s.inp,minHeight:60}}/><div style={{background:"#f8fafc",borderRadius:12,padding:12,marginBottom:10,border:"1px solid #ecdfc9"}}><div style={{fontSize:12,fontWeight:600,color:"#64748b",marginBottom:8}}>📍 Lokalizacja</div>{f.lat?<div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}><span style={{fontSize:13,color:"#22c55e",fontWeight:600}}>✅ {f.lat.toFixed(4)}, {f.lng.toFixed(4)}</span><button onClick={()=>sF({...f,lat:null,lng:null})} style={{background:"none",border:"none",color:"#ef4444",cursor:"pointer",fontSize:12}}>✕</button></div>:<><div style={{display:"flex",gap:6}}><input value={gq} onChange={e=>sGq(e.target.value)} onKeyDown={e=>e.key==="Enter"&&geo()} placeholder="Szukaj..." style={{...s.inp,marginBottom:0,flex:1,fontSize:13}}/><button onClick={geo} disabled={gl} style={{background:"#ecdfc9",border:"none",padding:"10px 14px",borderRadius:10,cursor:"pointer",fontSize:14}}>{gl?"⏳":"🔍"}</button></div>{gr.length>0&&<div style={{marginTop:8}}>{gr.map((r,i)=><div key={i} onClick={()=>{sF({...f,lat:+r.lat,lng:+r.lon});sGr([])}} style={{padding:"8px 10px",cursor:"pointer",borderRadius:8,fontSize:12,background:"#fff",marginBottom:4,border:"1px solid #ecdfc9"}}><div style={{fontWeight:600}}>{r.display_name.split(",")[0]}</div><div style={{color:"#94a3b8",fontSize:11}}>{r.display_name.slice(0,80)}</div></div>)}</div>}</>}</div><div style={s.pR}>{[["low","Niska ⬇️"],["medium","Średnia ➡️"],["high","Wysoka ⬆️"]].map(([v,l])=><button key={v} onClick={()=>sF({...f,priority:v})} style={{...s.pB,...(f.priority===v?s.pA:{})}}>{l}</button>)}</div><div style={s.row}><button onClick={()=>{setForm(null);setEdit(null)}} className="vy-btn" style={s.b2}>Anuluj</button><button onClick={()=>{if(!f.name)return;upTrip({places:edit?trip.places.map(p=>p.id===f.id?f:p):[...trip.places,f]});setForm(null);setEdit(null)}} className="vy-btn" style={s.b1}>Zapisz</button></div></div></div>};

const ExpenseForm=()=>{const[f,sF]=useState(edit||{id:uid(),name:"",amount:"",category:"Inne",date:new Date().toISOString().split("T")[0]});return<div style={s.modal}><div style={s.mc}><h3 style={s.fT}>💰 {edit?"Edytuj":"Dodaj"} wydatek</h3><input placeholder="Opis" value={f.name} onChange={e=>sF({...f,name:e.target.value})} style={s.inp}/><input placeholder="Kwota" type="number" value={f.amount} onChange={e=>sF({...f,amount:e.target.value})} style={s.inp}/><div style={s.cG}>{CATEGORIES.map(c=><button key={c} onClick={()=>sF({...f,category:c})} style={{...s.cB,...(f.category===c?{background:CAT_COLORS[c],color:"#fff"}:{})}}>{CAT_ICONS[c]} {c}</button>)}</div><input type="date" value={f.date} onChange={e=>sF({...f,date:e.target.value})} style={s.inp}/><div style={s.row}><button onClick={()=>{setForm(null);setEdit(null)}} className="vy-btn" style={s.b2}>Anuluj</button><button onClick={()=>{if(!f.name||!f.amount)return;upTrip({expenses:edit?trip.expenses.map(e=>e.id===f.id?{...f,amount:+f.amount}:e):[...trip.expenses,{...f,amount:+f.amount}]});setForm(null);setEdit(null)}} className="vy-btn" style={s.b1}>Zapisz</button></div></div></div>};

const NoteForm=()=>{const[f,sF]=useState(edit||{id:uid(),title:"",content:"",date:new Date().toISOString().split("T")[0],photos:[]});return<div style={s.modal}><div style={s.mc}><h3 style={s.fT}>📝 {edit?"Edytuj":"Dodaj"} notatkę</h3><input placeholder="Tytuł" value={f.title} onChange={e=>sF({...f,title:e.target.value})} style={s.inp}/><textarea placeholder="Treść..." value={f.content} onChange={e=>sF({...f,content:e.target.value})} style={{...s.inp,minHeight:100}}/><div style={{fontSize:13,fontWeight:600,color:"#475569",marginBottom:8}}>📷 Zdjęcia</div><PhotoUpload photos={f.photos||[]} onChange={photos=>sF({...f,photos})}/><div style={{...s.row,marginTop:12}}><button onClick={()=>{setForm(null);setEdit(null)}} className="vy-btn" style={s.b2}>Anuluj</button><button onClick={()=>{if(!f.title)return;upTrip({notes:edit?trip.notes.map(n=>n.id===f.id?f:n):[...trip.notes,f]});setForm(null);setEdit(null)}} className="vy-btn" style={s.b1}>Zapisz</button></div></div></div>};

const ItinForm=()=>{const[f,sF]=useState(edit||{id:uid(),day:"",title:"",items:[{time:"09:00",activity:""}]});const[showSugg,setShowSugg]=useState(null);const upI=(i,k,v)=>{const it=[...f.items];it[i]={...it[i],[k]:v};sF({...f,items:it})};const getTimePeriod=(time)=>{if(!time)return null;const h=parseInt(time);if(h>=6&&h<10)return"Rano (6-10)";if(h>=10&&h<13)return"Przedpołudnie (10-13)";if(h>=13&&h<17)return"Popołudnie (13-17)";if(h>=17&&h<22)return"Wieczór (17-21)";return null};
return<div style={s.modal}><div style={s.mc}><h3 style={s.fT}>🗓️ {edit?"Edytuj":"Dodaj"} plan dnia</h3><input type="date" value={f.day} onChange={e=>sF({...f,day:e.target.value})} style={s.inp}/><input placeholder="Tytuł dnia" value={f.title} onChange={e=>sF({...f,title:e.target.value})} style={s.inp}/><div style={{fontSize:13,fontWeight:600,color:"#475569",margin:"6px 0"}}>Aktywności:</div>{f.items.map((it,i)=><div key={i} style={{marginBottom:8}}><div style={{display:"flex",gap:6,alignItems:"center"}}><input type="time" value={it.time} onChange={e=>{upI(i,"time",e.target.value);setShowSugg(null)}} style={{...s.inp,width:100,flex:"none",marginBottom:0}}/><input placeholder="Aktywność" value={it.activity} onChange={e=>upI(i,"activity",e.target.value)} onFocus={()=>setShowSugg(i)} style={{...s.inp,flex:1,marginBottom:0}}/>{f.items.length>1&&<button onClick={()=>sF({...f,items:f.items.filter((_,j)=>j!==i)})} style={{background:"none",border:"none",color:"#ef4444",cursor:"pointer",fontSize:16}}>✕</button>}</div>{showSugg===i&&!it.activity&&<div style={{marginTop:6,maxHeight:150,overflowY:"auto",background:"#f8fafc",borderRadius:10,border:"1px solid #ecdfc9",padding:6}}>{(()=>{const period=getTimePeriod(it.time);const suggs=period?ACTIVITY_SUGGESTIONS[period]:Object.values(ACTIVITY_SUGGESTIONS).flat();return suggs.map((sg,j)=><button key={j} onClick={()=>{upI(i,"activity",sg);setShowSugg(null)}} style={{display:"block",width:"100%",padding:"8px 10px",background:"none",border:"none",borderBottom:"1px solid #f5e9d8",cursor:"pointer",textAlign:"left",fontSize:13,fontFamily:"'DM Sans',sans-serif",color:"#475569"}}>{sg}</button>)})()}</div>}</div>)}<button onClick={()=>sF({...f,items:[...f.items,{time:"",activity:""}]})} style={s.addB}>+ Aktywność</button><div style={s.row}><button onClick={()=>{setForm(null);setEdit(null)}} className="vy-btn" style={s.b2}>Anuluj</button><button onClick={()=>{if(!f.day)return;upTrip({itinerary:(edit?trip.itinerary.map(d=>d.id===f.id?f:d):[...trip.itinerary,f]).sort((a,b)=>a.day.localeCompare(b.day))});setForm(null);setEdit(null)}} className="vy-btn" style={s.b1}>Zapisz</button></div></div></div>};

if(!active)return(<DarkCtx.Provider value={darkMode}><div style={{...s.app,overflow:"auto",WebkitOverflowScrolling:"touch"}}><style>{CSS}</style><div style={s.home}><div style={s.hero}><div style={s.hPat}/><div style={{position:"relative",zIndex:1}}><div style={{display:"flex",justifyContent:"flex-end",marginBottom:8}}><button onClick={()=>setDarkMode(d=>!d)} style={{background:"rgba(255,255,255,.15)",border:"1px solid rgba(255,255,255,.25)",color:"#fff",padding:"6px 12px",borderRadius:20,cursor:"pointer",fontSize:13,fontWeight:600}}>{darkMode?"☀️ Jasny":"🌙 Ciemny"}</button></div><div style={{fontSize:48,marginBottom:4,filter:"drop-shadow(0 4px 12px rgba(0,0,0,.3))"}}>🧭</div><h1 style={{...s.hT,fontSize:32}}>Voyager</h1><p style={s.hS}>Twój osobisty planer podróży</p></div></div><div style={{padding:"24px 16px"}}>{trips.length===0?<div style={s.empty}><div style={{fontSize:64,marginBottom:16}}>🌎</div><h2 style={{color:"#1e293b",fontFamily:"'Playfair Display',serif",fontSize:22,margin:0}}>Brak podróży</h2><p style={{color:"#64748b",margin:"8px 0 24px"}}>Zaplanuj swoją pierwszą przygodę!</p><button onClick={()=>{setForm("trip");setEdit(null)}} className="vy-btn" style={s.b1}>+ Zaplanuj podróż</button></div>:<><div style={s.sH}><h2 style={s.sT}>Moje podróże</h2><button onClick={()=>{setForm("trip");setEdit(null)}} style={s.bSm}>+ Nowa</button></div><div style={{display:"flex",flexDirection:"column",gap:12}}>{trips.map((t,i)=>{const d=t.startDate&&t.endDate?Math.ceil((new Date(t.endDate)-new Date(t.startDate))/864e5)+1:0;const sp=t.expenses.reduce((s,e)=>s+e.amount,0);const du=t.startDate?Math.ceil((new Date(t.startDate+"T00:00:00")-new Date())/864e5):-999;return<div key={t.id} className="vy-card" onClick={()=>{setActive(t.id);setTab("Przegląd")}} style={{...s.card,animationDelay:`${i*.1}s`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}><div style={{fontSize:36,marginBottom:8}}>{t.coverEmoji}</div>{du>0&&<span style={{background:"#fff7ed",color:"#9a3412",padding:"4px 10px",borderRadius:20,fontSize:11,fontWeight:700}}>za {du} dni</span>}{du<=0&&du>-d&&<span style={{background:"#dcfce7",color:"#16a34a",padding:"4px 10px",borderRadius:20,fontSize:11,fontWeight:700}}>🎉 W toku</span>}</div><h3 style={{fontSize:18,fontWeight:700,fontFamily:"'Playfair Display',serif",margin:"4px 0"}}>{t.name||"Bez nazwy"}</h3><p style={{color:"#64748b",fontSize:14,marginBottom:8}}>{t.destination||"Cel nieznany"}</p><div style={{display:"flex",gap:14,color:"#94a3b8",fontSize:13,flexWrap:"wrap"}}>{d>0&&<span>📅 {d} dni</span>}<span>📍 {t.places.length}</span>{sp>0&&<span>💰 {sp.toFixed(0)} {t.currency}</span>}</div></div>})}</div></>}</div></div>{form==="trip"&&<TripForm/>}</div></DarkCtx.Provider>);

const days=trip.startDate&&trip.endDate?Math.ceil((new Date(trip.endDate)-new Date(trip.startDate))/864e5)+1:0;const spent=trip.expenses.reduce((s,e)=>s+e.amount,0);const byCat=CATEGORIES.map(c=>({c,t:trip.expenses.filter(e=>e.category===c).reduce((s,e)=>s+e.amount,0)})).filter(x=>x.t>0);const packing=trip.packing||[];const packedCount=packing.filter(p=>p.packed).length;

const TabContent=()=>{switch(tab){
case "Przegląd":const daysUntilTrip=trip.startDate?Math.ceil((new Date(trip.startDate+"T00:00:00")-new Date())/864e5):-999;const reminders=[];if(daysUntilTrip>0&&daysUntilTrip<=7)reminders.push({icon:"⏰",text:`Wyjazd za ${daysUntilTrip} dni! Sprawdź czy wszystko gotowe.`,color:"#f59e0b"});if(daysUntilTrip>0&&daysUntilTrip<=3&&packing.length>0&&packedCount<packing.length)reminders.push({icon:"🎒",text:`Nie spakowane: ${packing.length-packedCount} rzeczy!`,color:"#ef4444"});if(daysUntilTrip===1)reminders.push({icon:"✈️",text:"Jutro wyjazd! Sprawdź dokumenty i bilety.",color:"#ef4444"});if(daysUntilTrip===0)reminders.push({icon:"🎉",text:"Dziś wyjeżdżasz! Dobrej podróży!",color:"#22c55e"});if(trip.places.length>0&&trip.itinerary.length===0&&daysUntilTrip>0&&daysUntilTrip<=14)reminders.push({icon:"📅",text:"Masz miejsca ale brak planu dnia — czas zaplanować!",color:"#3b82f6"});if(trip.expenses.length===0&&daysUntilTrip>0&&daysUntilTrip<=7)reminders.push({icon:"💰",text:"Ustal budżet przed wyjazdem.",color:"#8b5cf6"});
return<div style={s.tc}><Countdown startDate={trip.startDate} endDate={trip.endDate}/>{reminders.length>0&&<div style={{marginBottom:12}}>{reminders.map((r,i)=><div key={i} style={{display:"flex",alignItems:"center",gap:10,padding:"12px 16px",background:"#fff",borderRadius:12,marginBottom:6,borderLeft:`4px solid ${r.color}`,border:"1px solid rgba(0,0,0,.06)"}}><span style={{fontSize:20}}>{r.icon}</span><span style={{fontSize:13,color:"#475569",fontWeight:500}}>{r.text}</span></div>)}</div>}<div style={s.oG}>{[["📍",trip.places.length,"Miejsc","Miejsca"],["📅",days||"—","Dni","Plan dnia"],["💰",spent.toFixed(0),trip.currency,"Budżet"],["📝",trip.notes.length,"Notatek","Notatki"],["✅",trip.places.filter(p=>p.visited).length+"/"+trip.places.length,"Odwiedzone","Miejsca"],["🎒",packedCount+"/"+packing.length,"Spakowane","Pakowanie"]].map(([i,v,l,t],k)=><div key={k} className="vy-card" onClick={()=>setTab(t)} style={{...s.stat,cursor:"pointer",transition:"transform .15s, box-shadow .15s"}} onMouseEnter={e=>{e.currentTarget.style.transform="translateY(-2px)";e.currentTarget.style.boxShadow="0 4px 16px rgba(0,0,0,.1)"}} onMouseLeave={e=>{e.currentTarget.style.transform="";e.currentTarget.style.boxShadow=""}}><div style={{fontSize:24}}>{i}</div><div style={s.stV}>{v}</div><div style={s.stL}>{l}</div></div>)}</div><WeatherWidget lat={trip.destLat} lng={trip.destLng} destination={trip.destination} onGeocode={(lat,lng)=>upTrip({destLat:lat,destLng:lng})}/><DestinationDiscovery destination={trip.destination} lat={trip.destLat} lng={trip.destLng} onAddPlace={p=>upTrip({places:[...trip.places,p]})}/>{trip.places.some(p=>p.lat)&&<div style={{...s.oS,padding:0,overflow:"hidden",cursor:"pointer",marginBottom:12}} onClick={()=>setTab("Mapa")}><div style={{height:180,position:"relative"}}><MiniMap trip={trip}/><div style={{position:"absolute",bottom:0,left:0,right:0,background:"linear-gradient(transparent,rgba(0,0,0,.6))",padding:"20px 16px 12px",color:"#fff",fontSize:13,fontWeight:600}}>🗺️ {trip.places.filter(p=>p.lat).length} miejsc na mapie</div></div></div>}{(spent>0||trip.places.length>0)&&<div style={s.oS}><h3 style={s.oST}>📊 Statystyki</h3>{spent>0&&days>0&&<div style={{fontSize:13,color:"#475569",marginBottom:6}}>💰 Średnio <strong>{(spent/days).toFixed(0)} {trip.currency}/dzień</strong></div>}{byCat.length>0&&<div style={{fontSize:13,color:"#475569",marginBottom:6}}>🏆 Top: <strong>{byCat.sort((a,b)=>b.t-a.t)[0].c}</strong> ({(byCat[0].t/spent*100).toFixed(0)}%)</div>}{trip.itinerary.length>0&&<div style={{fontSize:13,color:"#475569"}}>🗓️ <strong>{trip.itinerary.length}</strong> dni, <strong>{trip.itinerary.reduce((ss,d)=>ss+d.items.filter(i=>i.activity).length,0)}</strong> aktywności</div>}</div>}{byCat.length>0&&<div style={s.oS}><h3 style={s.oST}>💰 Wydatki</h3>{byCat.map(({c,t})=><div key={c} style={s.bR}><span style={s.bL}>{CAT_ICONS[c]} {c}</span><div style={s.bT}><div style={{...s.bF,width:`${(t/spent)*100}%`,background:CAT_COLORS[c]}}/></div><span style={s.bV}>{t.toFixed(0)}</span></div>)}</div>}<div style={{display:"flex",gap:8,marginTop:20,flexWrap:"wrap"}}><button onClick={()=>{setEdit(trip);setForm("trip")}} className="vy-btn" style={s.bO}>✏️ Edytuj</button><button onClick={()=>exportPDF(trip)} className="vy-btn" style={s.bO}>📄 PDF</button>{!deleteConfirm?<button onClick={()=>setDeleteConfirm(true)} style={{...s.bO,borderColor:"#ef4444",color:"#ef4444"}}>🗑️ Usuń</button>:<button onClick={()=>{setTrips(p=>p.filter(t=>t.id!==active));setActive(null)}} onBlur={()=>setTimeout(()=>setDeleteConfirm(false),200)} style={{...s.bO,background:"#ef4444",color:"#fff",borderColor:"#ef4444",fontWeight:700}}>Potwierdź usunięcie</button>}</div></div>;
case "Mapa":return<TripMap trip={trip} onAddPlace={p=>upTrip({places:[...trip.places,p]})}/>;
case "Miejsca":const geocodeOne=async(p)=>{const dest=trip?.destination||"";const dlat=trip?.destLat;const dlng=trip?.destLng;setGeocodingIds(g=>({...g,[p.id]:true}));setGeocodeErrors(e=>{const n={...e};delete n[p.id];return n});const cleanName=p.name.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu,"").replace(/["""„()]/g,"").trim();const searches=[{q:`${cleanName}, ${dest}`,useBounds:true},{q:cleanName,useBounds:true},{q:`${cleanName}, ${dest}`,useBounds:false},{q:cleanName,useBounds:false}];let found=false;for(const s of searches){if(found)break;try{let url=`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(s.q)}&limit=3&addressdetails=1`;if(s.useBounds&&dlat&&dlng){url+=`&viewbox=${dlng-0.5},${dlat+0.5},${dlng+0.5},${dlat-0.5}&bounded=1`}const r=await fetch(url,{headers:{"Accept-Language":"pl"}});const d=await r.json();if(d&&d[0]){setTrips(prev=>prev.map(t=>t.id===active?{...t,places:t.places.map(x=>x.id===p.id?{...x,lat:+d[0].lat,lng:+d[0].lon,address:d[0].display_name||""}:x)}:t));found=true;break}}catch{}if(!found)await new Promise(ok=>setTimeout(ok,600))}setGeocodingIds(g=>{const n={...g};delete n[p.id];return n});if(!found)setGeocodeErrors(e=>({...e,[p.id]:true}));};const geocodeAll=async()=>{const missing=trip.places.filter(p=>!p.lat);for(const p of missing){await geocodeOne(p);await new Promise(ok=>setTimeout(ok,700))}};return<div style={s.tc}><button onClick={()=>{setForm("place");setEdit(null)}} className="vy-btn" style={s.b1}>+ Dodaj miejsce</button>{trip.places.some(p=>!p.lat)&&<button onClick={geocodeAll} style={{...s.addB,marginTop:8,color:"#3b82f6",borderColor:"#3b82f6"}}>🔄 Znajdź GPS dla {trip.places.filter(p=>!p.lat).length} miejsc</button>}{!trip.places.length?<div style={s.eT}><div style={{fontSize:48}}>📍</div><p>Dodaj miejsca</p></div>:<div style={{display:"flex",flexDirection:"column",gap:10,marginTop:16}}>{trip.places.map(p=><div key={p.id} className="vy-card" style={s.plC}><div style={{display:"flex",gap:12,alignItems:"flex-start",flex:1}}><button onClick={()=>upTrip({places:trip.places.map(x=>x.id===p.id?{...x,visited:!x.visited}:x)})} style={{...s.chk,...(p.visited?s.chkO:{})}}>{p.visited&&"✓"}</button><div style={{flex:1}}><div style={{fontSize:15,fontWeight:600,textDecoration:p.visited?"line-through":"none",opacity:p.visited?.5:1}}>{p.name}</div>{p.description&&<div style={{fontSize:13,color:"#64748b",marginTop:2}}>{p.description}</div>}{p.address&&<div style={{fontSize:12,color:"#94a3b8",marginTop:4}}>📍 {p.address.split(",").slice(0,3).join(",")}</div>}{p.lat&&<div style={{fontSize:11,color:"#94a3b8",marginTop:2,fontFamily:"monospace"}}>🌐 {p.lat.toFixed(5)}, {p.lng.toFixed(5)}</div>}<div style={{display:"flex",gap:6,marginTop:6,flexWrap:"wrap"}}><span style={{...s.tag,background:p.priority==="high"?"#fef2f2":p.priority==="medium"?"#fffbeb":"#f0fdf4",color:PRI_COLORS[p.priority]}}>{p.priority==="high"?"⬆️":p.priority==="medium"?"➡️":"⬇️"}</span>{p.lat?<span style={{...s.tag,background:"#dcfce7",color:"#16a34a"}}>🗺️ Na mapie</span>:<button onClick={()=>!geocodingIds[p.id]&&geocodeOne(p)} style={{...s.tag,background:geocodeErrors[p.id]?"#fff7ed":geocodingIds[p.id]?"#eff6ff":"#fef2f2",color:geocodeErrors[p.id]?"#ea580c":geocodingIds[p.id]?"#3b82f6":"#ef4444",border:"none",cursor:geocodingIds[p.id]?"default":"pointer",opacity:geocodingIds[p.id]?.7:1}}>{geocodingIds[p.id]?"⏳ Szukam...":geocodeErrors[p.id]?"❌ Nie znaleziono":"🔄 Szukaj GPS"}</button>}</div></div></div><div style={s.acts}><button onClick={()=>{setEdit(p);setForm("place")}} style={s.iB}>✏️</button><button onClick={()=>upTrip({places:trip.places.filter(x=>x.id!==p.id)})} style={s.iB}>🗑️</button></div></div>)}</div>}</div>;
case "Plan dnia":return<div style={s.tc}><button onClick={()=>{setForm("itin");setEdit(null)}} className="vy-btn" style={s.b1}>+ Dodaj plan dnia</button>{!trip.itinerary.length?<div style={s.eT}><div style={{fontSize:48}}>🗓️</div><p>Zaplanuj dni</p></div>:<div style={{display:"flex",flexDirection:"column",gap:10,marginTop:16}}>{trip.itinerary.map(d=><div key={d.id} className="vy-card" style={s.dC}><div style={s.dH}><div><div style={{fontSize:14,fontWeight:700,color:"#9a3412",textTransform:"capitalize"}}>{new Date(d.day+"T12:00:00").toLocaleDateString("pl-PL",{weekday:"long",day:"numeric",month:"long"})}</div>{d.title&&<div style={{fontSize:13,color:"#64748b",marginTop:2}}>{d.title}</div>}</div><div style={s.acts}><button onClick={()=>{setEdit(d);setForm("itin")}} style={s.iB}>✏️</button><button onClick={()=>upTrip({itinerary:trip.itinerary.filter(x=>x.id!==d.id)})} style={s.iB}>🗑️</button></div></div><div style={{padding:"12px 16px"}}>{d.items.filter(x=>x.activity).map((it,i)=><div key={i} style={{display:"flex",alignItems:"center",gap:12,padding:"8px 0",borderBottom:"1px solid #f8fafc"}}><div style={{width:8,height:8,borderRadius:"50%",background:"#9a3412",flexShrink:0}}/><div style={{fontSize:13,fontWeight:600,color:"#9a3412",fontFamily:"monospace",width:50}}>{it.time}</div><div style={{fontSize:14,color:"#475569"}}>{it.activity}</div></div>)}</div></div>)}</div>}</div>;
case "Budżet":return<div style={s.tc}><div style={{background:"#fff",borderRadius:14,padding:20,marginBottom:16,textAlign:"center",border:"1px solid rgba(0,0,0,.06)"}}><div style={{fontSize:14,color:"#64748b"}}>Łączne wydatki</div><div style={{fontSize:32,fontWeight:700,fontFamily:"monospace"}}>{spent.toFixed(2)} <span style={{fontSize:18,color:"#94a3b8"}}>{trip.currency}</span></div>{days>0&&<div style={{fontSize:13,color:"#94a3b8",marginTop:4}}>~ {(spent/days).toFixed(0)} {trip.currency}/dzień</div>}</div><CurrencyConverter baseCurrency={trip.currency}/><button onClick={()=>{setForm("expense");setEdit(null)}} className="vy-btn" style={s.b1}>+ Dodaj wydatek</button>{!trip.expenses.length?<div style={s.eT}><div style={{fontSize:48}}>💰</div><p>Śledź wydatki</p></div>:<><div style={{display:"flex",flexDirection:"column",gap:10,marginTop:12}}>{[...trip.expenses].sort((a,b)=>b.date.localeCompare(a.date)).map(e=><div key={e.id} className="vy-card" style={s.exC}><div style={{display:"flex",alignItems:"center",gap:12,flex:1}}><div style={{...s.cD,background:CAT_COLORS[e.category]}}>{CAT_ICONS[e.category]}</div><div><div style={{fontSize:14,fontWeight:600}}>{e.name}</div><div style={{fontSize:12,color:"#94a3b8"}}>{e.category} • {e.date}</div></div></div><div style={{fontWeight:700,fontSize:15,fontFamily:"monospace",whiteSpace:"nowrap"}}>{e.amount.toFixed(2)}</div><div style={s.acts}><button onClick={()=>{setEdit(e);setForm("expense")}} style={s.iB}>✏️</button><button onClick={()=>upTrip({expenses:trip.expenses.filter(x=>x.id!==e.id)})} style={s.iB}>🗑️</button></div></div>)}</div></>}</div>;
case "Pakowanie":return<div style={s.tc}>{packing.length===0?<><div style={s.eT}><div style={{fontSize:48}}>🎒</div><p>Utwórz listę</p></div><button onClick={()=>{const items=[];Object.entries(PACK_TEMPLATES).forEach(([cat,things])=>{things.forEach(name=>{items.push({id:uid(),name,category:cat,packed:false})})});upTrip({packing:items})}} className="vy-btn" style={s.b1}>📋 Załaduj szablon</button><button onClick={()=>{upTrip({packing:[{id:uid(),name:"",category:"Inne",packed:false}]})}} style={{...s.addB,marginTop:8}}>+ Pusta lista</button></>:<><div style={{background:"#fff",borderRadius:14,padding:16,marginBottom:16,border:"1px solid rgba(0,0,0,.06)",textAlign:"center"}}><div style={{fontSize:14,color:"#64748b"}}>Spakowane</div><div style={{fontSize:28,fontWeight:700,fontFamily:"monospace"}}>{packedCount}/{packing.length}</div><div style={{height:8,background:"#fdf3e7",borderRadius:4,overflow:"hidden",marginTop:8}}><div style={{height:"100%",borderRadius:4,background:packedCount===packing.length?"#22c55e":"#3b82f6",width:`${packing.length>0?(packedCount/packing.length*100):0}%`,transition:"width .3s"}}/></div></div>{Object.keys(PACK_TEMPLATES).map(cat=>{const items=packing.filter(p=>p.category===cat);if(!items.length)return null;const cp=items.filter(i=>i.packed).length;return<div key={cat} style={{marginBottom:12}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}><h4 style={{fontSize:14,fontWeight:700,color:"#9a3412"}}>{cat} ({cp}/{items.length})</h4><button onClick={()=>{const all=items.every(i=>i.packed);upTrip({packing:packing.map(p=>p.category===cat?{...p,packed:!all}:p)})}} style={{background:"none",border:"none",cursor:"pointer",fontSize:12,color:"#3b82f6",fontWeight:600}}>{items.every(i=>i.packed)?"Odznacz":"Zaznacz"}</button></div>{items.map(item=><div key={item.id} style={{display:"flex",alignItems:"center",gap:10,padding:"8px 12px",background:"#fff",borderRadius:10,marginBottom:4,border:"1px solid rgba(0,0,0,.06)"}}><button onClick={()=>upTrip({packing:packing.map(p=>p.id===item.id?{...p,packed:!p.packed}:p)})} style={{...s.chk,width:22,height:22,...(item.packed?s.chkO:{})}}>{item.packed&&"✓"}</button><span style={{flex:1,fontSize:14,textDecoration:item.packed?"line-through":"none",opacity:item.packed?.5:1,color:"#475569"}}>{item.name}</span><button onClick={()=>upTrip({packing:packing.filter(p=>p.id!==item.id)})} style={s.iB}>✕</button></div>)}</div>})}<div style={{display:"flex",gap:6,marginBottom:10}}><input value={packInput} onChange={e=>setPackInput(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&packInput.trim()){upTrip({packing:[...packing,{id:uid(),name:packInput.trim(),category:"Inne",packed:false}]});setPackInput("")}}} placeholder="Dodaj rzecz..." style={{...s.inp,flex:1,marginBottom:0}}/><button onClick={()=>{if(packInput.trim()){upTrip({packing:[...packing,{id:uid(),name:packInput.trim(),category:"Inne",packed:false}]});setPackInput("")}}} disabled={!packInput.trim()} style={{background:"#9a3412",color:"#fff",border:"none",padding:"12px 16px",borderRadius:10,cursor:"pointer",fontWeight:700,fontSize:14,flexShrink:0,opacity:packInput.trim()?1:.4}}>+</button></div>{!clearPackConfirm?<button onClick={()=>setClearPackConfirm(true)} style={{...s.bO,marginTop:8,borderColor:"#ef4444",color:"#ef4444",width:"100%"}}>🗑️ Wyczyść</button>:<button onClick={()=>{upTrip({packing:[]});setClearPackConfirm(false)}} onBlur={()=>setTimeout(()=>setClearPackConfirm(false),200)} style={{...s.bO,marginTop:8,background:"#ef4444",color:"#fff",borderColor:"#ef4444",width:"100%",fontWeight:700}}>Potwierdź wyczyszczenie</button>}</>}</div>;
case "Notatki":return<div style={s.tc}><button onClick={()=>{setForm("note");setEdit(null)}} className="vy-btn" style={s.b1}>+ Dodaj notatkę</button>{!trip.notes.length?<div style={s.eT}><div style={{fontSize:48}}>📝</div><p>Zapisuj myśli</p></div>:<div style={{display:"flex",flexDirection:"column",gap:12,marginTop:16}}>{trip.notes.map(n=><div key={n.id} className="vy-card" style={s.nC}>{n.photos&&n.photos.length>0&&<div style={{display:"flex",overflowX:"auto",gap:2}}>{n.photos.map((p,i)=><img key={i} src={p.data} style={{width:n.photos.length===1?"100%":200,height:180,objectFit:"cover",flexShrink:0}} alt=""/>)}</div>}<div style={{padding:16}}><h4 style={{fontSize:16,fontWeight:700,fontFamily:"'Playfair Display',serif",marginBottom:6}}>{n.title}</h4><p style={{fontSize:14,color:"#475569",lineHeight:1.6,whiteSpace:"pre-wrap"}}>{n.content}</p><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:10}}><span style={{fontSize:12,color:"#94a3b8"}}>{n.date}{n.photos?.length?` • 📷 ${n.photos.length}`:""}</span><div style={s.acts}><button onClick={()=>{setEdit(n);setForm("note")}} style={s.iB}>✏️</button><button onClick={()=>upTrip({notes:trip.notes.filter(x=>x.id!==n.id)})} style={s.iB}>🗑️</button></div></div></div></div>)}</div>}</div>;
case "Tłumacz":return<div style={s.tc}><div style={{background:"#fff",borderRadius:14,padding:16,border:"1px solid rgba(0,0,0,.06)",marginBottom:16,textAlign:"center"}}><div style={{fontSize:36,marginBottom:8}}>🌍</div><h3 style={{fontSize:18,fontWeight:700,fontFamily:"'Playfair Display',serif"}}>Rozmówki turystyczne</h3><p style={{fontSize:13,color:"#64748b",marginTop:4}}>🇬🇧 🇩🇪 🇫🇷 🇪🇸 🇮🇹</p></div>{Object.entries(PHRASES).map(([cat,phrases])=><div key={cat} style={{background:"#fff",borderRadius:14,border:"1px solid rgba(0,0,0,.06)",marginBottom:12,overflow:"hidden"}}><div style={{padding:"14px 16px",borderBottom:"1px solid #f5e9d8",fontWeight:700,fontSize:14,color:"#9a3412"}}>{cat}</div><div style={{padding:"4px 0"}}>{Object.entries(phrases).map(([pl,trans],i)=><div key={i} style={{padding:"12px 16px",borderBottom:"1px solid #f5e9d8"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}><div style={{fontSize:15,fontWeight:700,color:"#1e293b"}}>🇵🇱 {pl}</div><button onClick={()=>{if(window.speechSynthesis){const u=new SpeechSynthesisUtterance(pl);u.lang="pl-PL";window.speechSynthesis.speak(u)}}} style={{background:"#fff7ed",border:"none",borderRadius:8,padding:"4px 8px",cursor:"pointer",fontSize:14,flexShrink:0}}>🔊</button></div><div style={{display:"flex",flexDirection:"column",gap:4}}>{trans.map((t,j)=><div key={j} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"6px 10px",background:j%2===0?"#f8fafc":"#fff",borderRadius:8}}><div style={{display:"flex",alignItems:"center",gap:8,flex:1}}><span style={{fontSize:14}}>{LANG_FLAGS[j]}</span><span style={{fontSize:13,color:"#475569"}}>{t}</span></div><button onClick={()=>{if(window.speechSynthesis){const u=new SpeechSynthesisUtterance(t);u.lang=LANG_CODES[j];window.speechSynthesis.speak(u)}}} style={{background:"none",border:"none",cursor:"pointer",fontSize:13,flexShrink:0,padding:"2px 6px",opacity:.6}}>🔊</button></div>)}</div></div>)}</div></div>)}</div>;
case "SOS":return<div style={s.tc}><div style={{background:"linear-gradient(135deg,#dc2626,#ef4444)",borderRadius:14,padding:20,marginBottom:16,textAlign:"center",color:"#fff"}}><div style={{fontSize:36,marginBottom:8}}>🆘</div><h3 style={{fontSize:18,fontWeight:700}}>Informacje awaryjne</h3><p style={{fontSize:13,opacity:.8,marginTop:4}}>Numery alarmowe i ambasady</p></div><div style={{background:"#fef2f2",borderRadius:14,padding:16,marginBottom:16,border:"1px solid #fecaca"}}><div style={{fontSize:14,fontWeight:700,color:"#dc2626",marginBottom:8}}>📞 Numer alarmowy UE: 112</div><div style={{fontSize:13,color:"#7f1d1d"}}>Działa we wszystkich krajach UE — pogotowie, straż, policja</div></div>{Object.entries(EMERGENCY_DATA).map(([country,data])=><div key={country} style={{background:"#fff",borderRadius:14,border:"1px solid rgba(0,0,0,.06)",marginBottom:10,overflow:"hidden"}}><div style={{padding:"14px 16px",borderBottom:"1px solid #f5e9d8",fontWeight:700,fontSize:15,color:"#9a3412"}}>{country}</div><div style={{padding:16}}><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:12}}><div style={{background:"#fef2f2",borderRadius:10,padding:10,textAlign:"center"}}><div style={{fontSize:11,color:"#94a3b8",fontWeight:600}}>Pogotowie</div><div style={{fontSize:16,fontWeight:700,color:"#dc2626",fontFamily:"monospace"}}>{data.tel}</div></div><div style={{background:"#eff6ff",borderRadius:10,padding:10,textAlign:"center"}}><div style={{fontSize:11,color:"#94a3b8",fontWeight:600}}>Policja</div><div style={{fontSize:16,fontWeight:700,color:"#9a3412",fontFamily:"monospace"}}>{data.police}</div></div></div><div style={{fontSize:13,color:"#475569",marginBottom:10,lineHeight:1.6}}>{data.amb}</div><div style={{display:"flex",flexDirection:"column",gap:4}}>{data.tips.map((tip,i)=><div key={i} style={{fontSize:12,color:"#64748b",paddingLeft:16,position:"relative"}}><span style={{position:"absolute",left:0}}>💡</span>{tip}</div>)}</div></div></div>)}</div>;
case "Galeria":const allPhotos=[];trip.notes.forEach(n=>{(n.photos||[]).forEach(p=>{allPhotos.push({...p,noteTitle:n.title,noteDate:n.date})})});return<div style={s.tc}><div style={{background:"#fff",borderRadius:14,padding:16,border:"1px solid rgba(0,0,0,.06)",marginBottom:16,textAlign:"center"}}><div style={{fontSize:36,marginBottom:8}}>📸</div><h3 style={{fontSize:18,fontWeight:700,fontFamily:"'Playfair Display',serif"}}>Galeria podróży</h3><p style={{fontSize:13,color:"#64748b",marginTop:4}}>{allPhotos.length} zdjęć</p></div>{allPhotos.length===0?<div style={s.eT}><div style={{fontSize:48}}>📷</div><p>Dodaj zdjęcia w zakładce Notatki</p></div>:<>{[...new Set(allPhotos.map(p=>p.noteDate))].sort().reverse().map(date=><div key={date} style={{marginBottom:20}}><div style={{fontSize:14,fontWeight:700,color:"#9a3412",marginBottom:10,display:"flex",alignItems:"center",gap:8}}><div style={{width:8,height:8,borderRadius:"50%",background:"#9a3412"}}/>{new Date(date+"T12:00:00").toLocaleDateString("pl-PL",{day:"numeric",month:"long",year:"numeric"})}</div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6}}>{allPhotos.filter(p=>p.noteDate===date).map((p,i)=><div key={i} style={{borderRadius:12,overflow:"hidden",position:"relative",aspectRatio:"1",border:"1px solid rgba(0,0,0,.06)"}}><img src={p.data} style={{width:"100%",height:"100%",objectFit:"cover"}} alt=""/><div style={{position:"absolute",bottom:0,left:0,right:0,background:"linear-gradient(transparent,rgba(0,0,0,.7))",padding:"16px 10px 8px",color:"#fff",fontSize:11,fontWeight:600}}>{p.noteTitle}</div></div>)}</div></div>)}</>}</div>;
default:return null}};

return(<DarkCtx.Provider value={darkMode}><div style={s.app}><style>{CSS}</style><div style={s.dHd}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><button onClick={()=>setActive(null)} style={s.back}>← Powrót</button><div style={{display:"flex",gap:8}}><button onClick={()=>setDarkMode(d=>!d)} style={{...s.aiTB,fontSize:16}}>{darkMode?"☀️":"🌙"}</button><button onClick={()=>setShowAI(true)} style={s.aiTB}>🤖 AI</button></div></div><div style={{display:"flex",alignItems:"center",gap:12}}><span style={{fontSize:24}}>{trip.coverEmoji}</span><div><h2 style={{...s.dT,fontSize:18}}>{trip.name}</h2><p style={s.dD}>{trip.destination}{trip.startDate&&` • ${trip.startDate} → ${trip.endDate}`}</p></div></div></div><div style={s.contentArea}>{tab==="Więcej"?<div style={s.tc}><h3 style={{fontSize:18,fontWeight:700,fontFamily:"'Playfair Display',serif",marginBottom:16}}>Więcej</h3><div style={{display:"flex",flexDirection:"column",gap:8}}>{["Pakowanie","Notatki","Tłumacz","SOS","Galeria"].map(t=><button key={t} onClick={()=>setTab(t)} style={{background:darkMode?"#2a1d14":"#fff",border:darkMode?"1px solid rgba(255,255,255,.08)":"1px solid rgba(0,0,0,.06)",borderRadius:14,padding:"16px 20px",display:"flex",alignItems:"center",gap:14,cursor:"pointer",fontFamily:"'DM Sans',sans-serif",fontSize:15,fontWeight:600,color:darkMode?"#f1f5f9":"#1e293b"}}><span style={{fontSize:24}}>{ICONS[t]}</span><span>{t}</span></button>)}</div></div>:<TabContent/>}</div><div style={s.btmBar}>{[...["Przegląd","Mapa","Miejsca","Plan dnia","Budżet"],["Więcej"]].flat().map(t=>{const icon=t==="Więcej"?"⋯":ICONS[t];const active2=t==="Więcej"?["Pakowanie","Notatki","Tłumacz","SOS","Galeria"].includes(tab):tab===t;return<button key={t} onClick={()=>setTab(t)} style={{...s.btmBtn,...(active2?s.btmA:{})}}><span style={{fontSize:20}}>{icon}</span><span style={{fontSize:9,marginTop:1}}>{t==="Plan dnia"?"Plan":t}</span></button>})}</div>{form==="trip"&&<TripForm/>}{form==="place"&&<PlaceForm/>}{form==="expense"&&<ExpenseForm/>}{form==="note"&&<NoteForm/>}{form==="itin"&&<ItinForm/>}{showAI&&<AIChat trip={trip} onClose={()=>setShowAI(false)} onAddPlaces={arr=>upTrip({places:[...trip.places,...arr]})} onUpdatePlace={(id,lat,lng,addr)=>setTrips(p=>p.map(t=>t.id===active?{...t,places:t.places.map(pl=>pl.id===id?{...pl,lat,lng,address:addr||""}:pl)}:t))} onAddToItinerary={item=>upTrip({itinerary:[...trip.itinerary,item].sort((a,b)=>a.day.localeCompare(b.day))})}/>}</div></DarkCtx.Provider>)}

