const CSS=`@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600;700&family=DM+Sans:wght@400;500;600;700&family=DM+Mono:wght@400;500&display=swap');*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}html,body{font-family:'DM Sans',sans-serif;overscroll-behavior:none;-webkit-overflow-scrolling:touch;height:100%;overflow:hidden}#root{height:100%}input,textarea,select{font-size:16px!important}@keyframes fadeUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}@keyframes cardIn{from{opacity:0;transform:scale(.96) translateY(10px)}to{opacity:1;transform:scale(1) translateY(0)}}@keyframes shimmer{0%{background-position:-200% 0}100%{background-position:200% 0}}::-webkit-scrollbar{width:0;display:none}.leaflet-container{font-family:'DM Sans',sans-serif!important;z-index:1!important}.leaflet-pane{z-index:1!important}.leaflet-top,.leaflet-bottom{z-index:2!important}@supports(padding-bottom:env(safe-area-inset-bottom)){.btm-bar-safe{padding-bottom:calc(8px + env(safe-area-inset-bottom))!important}}.vy-card{transition:transform .18s cubic-bezier(.2,.8,.2,1),box-shadow .18s ease,border-color .18s ease}.vy-card:active{transform:scale(.98);box-shadow:0 1px 6px rgba(15,23,42,.06)!important}.vy-btn{transition:transform .15s cubic-bezier(.2,.8,.2,1),box-shadow .15s ease,filter .15s ease}.vy-btn:active{transform:scale(.96);filter:brightness(.96)}.vy-tab{transition:color .2s ease,border-color .2s ease}.vy-fab{transition:transform .2s cubic-bezier(.34,1.56,.64,1),box-shadow .2s ease}.vy-fab:active{transform:scale(.92) rotate(-6deg)}.vy-chip{transition:all .15s ease}.vy-chip:active{transform:scale(.94)}`;
